SELECT try_divide(SUM(`final_approved`),SUM(`payments_sent`)) AS `final_approval_rate`, SUM(`payments_sent`) AS `payments_sent`
FROM `workspace`.`approval_copilot`.`gold_approval_daily`
WHERE `country` = 'BR' AND `is_cross_border` = true AND `business_date` BETWEEN DATE'2026-08-01' AND DATE'2026-08-31';
